async function api(path,opt={}){const headers={"Content-Type":"application/json",...(opt.headers||{})};if(state.token)headers.Authorization="Bearer "+state.token;const res=await fetch(API+path,{...opt,headers});let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.error||"تعذر تنفيذ الطلب");return data}
