async function loadStats(){const paint=(id,value)=>{const el=$(id);if(el)el.textContent=Number(value||0).toLocaleString('ar-EG')};try{const [server,metrics]=await Promise.all([api('/api/public/server'),api('/api/public/metrics')]);paint('#membersCount',server.memberCount||metrics.users);paint('#onlineCount',server.onlineCount);paint('#visitCount',metrics.visits);paint('#messageCount',metrics.messages);const hint=$("#serverHint");if(hint)hint.textContent=(server.name||'MLD')+' • '+(server.ownerName||'فهد المطيري')}catch{try{const metrics=await api('/api/public/metrics');paint('#membersCount',metrics.users);paint('#visitCount',metrics.visits);paint('#messageCount',metrics.messages)}catch{}}}
