document.addEventListener("submit",async e=>{const ticketReply=e.target.closest("#ticketReplyForm");if(ticketReply){e.preventDefault();const content=String(ticketReply.elements.content.value||"").trim();if(!content)return;const button=ticketReply.querySelector('button[type="submit"],button:not([type])');if(button){button.disabled=true;button.textContent="جارٍ الإرسال…"}try{await api("/api/community/tickets/"+encodeURIComponent(ticketReply.dataset.ticketId)+"/messages",{method:"POST",body:JSON.stringify({content})});toast("تم إرسال الرد");render()}catch(err){toast(err.message)}finally{if(button&&button.isConnected){button.disabled=false;button.textContent="إرسال الرد"}}return}const f=e.target.closest("[data-bot-config]");if(!f)return;e.preventDefault();try{const commands=JSON.parse(f.elements.commands_json.value||"[]");if(!Array.isArray(commands))throw new Error("الأوامر يجب أن تكون مصفوفة JSON");const d=await api("/api/bots/"+encodeURIComponent(f.dataset.botConfig)+"/config",{method:"PATCH",body:JSON.stringify({bot_type:f.elements.bot_type.value,prefix:f.elements.prefix.value,commands,welcomeMessage:f.elements.welcomeMessage.value,welcomeChannelId:f.elements.welcomeChannelId.value,supportRooms:[...(f.elements.supportRooms?.selectedOptions||[])].map(o=>o.value),supportTextChannelId:f.elements.supportTextChannelId?.value,greetMessage:f.elements.greetMessage?.value,adminRole:f.elements.adminRole?.value,mentionAdmin:!!f.elements.mentionAdmin?.checked,startingBalance:f.elements.startingBalance?.value,loanInterest:f.elements.loanInterest?.value,maxLoan:f.elements.maxLoan?.value,dailyReward:f.elements.dailyReward?.value,enabledGames:[...f.querySelectorAll("[data-enabled-game]:checked")].map(o=>o.value),gamePoints:f.elements.gamePoints?.value,musicVolume:f.elements.musicVolume?.value,musicQueueLimit:f.elements.musicQueueLimit?.value,musicAutoplay:!!f.elements.musicAutoplay?.checked,applicationsChannelId:f.elements.applicationsChannelId?.value,ticketsChannelId:f.elements.ticketsChannelId?.value,supportRoleId:f.elements.supportRoleId?.value,juniorRoleId:f.elements.juniorRoleId?.value,automodEnabled:f.elements.automodEnabled.checked,antiLinksEnabled:f.elements.antiLinksEnabled.checked,antiSpamEnabled:f.elements.antiSpamEnabled.checked,blockedWords:f.elements.blockedWords.value,modLogChannelId:f.elements.modLogChannelId.value,leaveChannelId:f.elements.leaveChannelId.value,leaveMessage:f.elements.leaveMessage.value})});toast(d.message);render()}catch(err){toast(err.message)}});
document.addEventListener("submit",async e=>{const f=e.target;if(f.id==="botForm"&&f.dataset.verifiedGuildId!==String(f.elements.guild_id.value||"").trim()){e.preventDefault();toast("تحقق من السيرفر والصلاحيات قبل إضافة البوت");return}if(!["loginForm","registerForm","chatForm","reviewForm","groupForm","ticketForm","pigeonForm","cinemaForm","botForm","announcementForm","roomForm","passwordForm","profileForm","ownerBroadcastForm","ownerTicketQuestionsForm","ownerApplicationQuestionsForm","cinemaSessionForm","cinemaBotForm","cinemaMovieForm","ownerDmForm"].includes(f.id))return;e.preventDefault();const submit=f.querySelector('button[type="submit"],button:not([type])');if(submit){submit.disabled=true;submit.dataset.originalText=submit.textContent;submit.textContent="جارٍ التنفيذ…"}try{const data=Object.fromEntries(new FormData(f));if(f.querySelector("[data-user-picker-input]")&&!f.querySelector("[data-user-picker-id]")?.value)throw new Error("اختر عضوًا من اقتراحات Discord أولًا");let path="",method="POST";if(f.id==="passwordForm"){if(data.new_password!==data.confirm_password)throw new Error("كلمتا المرور غير متطابقتين");path="/api/auth/change-password"}if(f.id==="profileForm"){path="/api/users/me";method="PATCH"}if(f.id==="loginForm")path="/api/auth/login";if(f.id==="registerForm")path="/api/auth/register";if(f.id==="chatForm")path="/api/community/chat";if(f.id==="reviewForm")path="/api/community/reviews";if(f.id==="groupForm")path="/api/community/groups";if(f.id==="ticketForm")path="/api/community/tickets";if(f.id==="pigeonForm")path="/api/community/pigeon";if(f.id==="ownerDmForm")path="/api/community/pigeon";if(f.id==="cinemaForm")path="/api/community/cinema";if(f.id==="cinemaSessionForm")path="/api/community/cinema/session";if(f.id==="cinemaBotForm")path="/api/community/cinema/bots";if(f.id==="cinemaMovieForm")path="/api/community/cinema/catalog";if(f.id==="botForm")path="/api/bots";if(f.id==="announcementForm"){path="/api/community/owner/announcement";method="PATCH";data={text:data.text,color:data.color,enabled:f.elements.enabled.checked}}if(f.id==="ownerBroadcastForm"){path="/api/community/owner/broadcast"}if(f.id==="ownerTicketQuestionsForm"||f.id==="ownerApplicationQuestionsForm"){const parsed=JSON.parse(data.value);if(!Array.isArray(parsed))throw new Error("الأسئلة يجب أن تكون قائمة JSON");path="/api/community/settings/"+(f.id==="ownerTicketQuestionsForm"?"ticket_questions":"application_questions");method="PATCH";data={value:parsed}}if(f.id==="roomForm"){path="/api/community/rooms";data={name:data.roomName,voice_name:data.voiceName,is_private:f.elements.is_private.checked}}const d=await api(path,{method,body:JSON.stringify(data)});if(f.id==="loginForm"){state.token=d.token;state.user=d.user;save();$("#modal").classList.remove("open");renderHeader();render();toast("تم تسجيل الدخول")}else if(f.id==="registerForm"){state.token=d.token;state.user=d.user;save();$("#modal").classList.remove("open");renderHeader();render();toast("تم إنشاء الحساب بنجاح")}else if(f.id==="passwordForm"){toast(d.message||"تم تغيير كلمة المرور");f.reset()}else if(f.id==="profileForm"){state.user=d.user||state.user;save();renderHeader();toast("تم حفظ الملف الشخصي");render()}else if(f.id==="chatForm"){f.reset();if(f.elements.room_id)f.elements.room_id.value=state.activeRoom||"public";toast("تم إرسال الرسالة");await refreshChatMessages()}else{toast(d.message||"تم التنفيذ");render()}}catch(err){toast(err.message)}finally{if(submit&&submit.isConnected){submit.disabled=false;submit.textContent=submit.dataset.originalText||"إرسال"}}});
